import numpy as np
A=np.array([[8,9,8],[8,8,9],[9,9,8]])
B=np.array([[8,9,8,9,8,8],[8,8,9,9,8,9],[9,9,8,8,9,8],[8,9,8,8,9,9],[9,8,9,9,8,8],[8,8,9,8,9,8]])
for k,v in {'TL':B[:3,:3],'TR':B[:3,3:],'BL':B[3:,:3],'BR':B[3:,3:]}.items():
    for name,c in [('A',A),('r90',np.rot90(A)),('r180',np.rot90(A,2)),('r270',np.rot90(A,3)),('lr',np.fliplr(A)),('ud',np.flipud(A)),('T',A.T),('anti',np.fliplr(A.T))]:
        if np.array_equal(v,c): print(k,'=',name)
print('match quadrant rule:', np.array_equal(B, np.block([[A,np.rot90(A,3)],[np.rot90(A),np.rot90(A,2)]])))
